WITH enriched AS (SELECT id, product_id, quantity, last_restock, LAG(quantity) OVER (PARTITION BY product_id ORDER BY quantity, id) AS prev_quantity, LEAD(quantity) OVER (PARTITION BY product_id ORDER BY quantity, id) AS next_quantity, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity, id) AS event_seq FROM inventory WHERE last_restock < '2025-05-01') SELECT s.id, s.product_id, s.quantity, s.last_restock, s.prev_quantity, s.next_quantity, (SELECT SUM(t2.revenue) FROM store_sales t2 WHERE t2.product_id = s.product_id) AS sum_store_sale_revenue FROM enriched s ORDER BY sum_store_sale_revenue DESC;
